import {CreationStudio} from './studio.js';
import {makeRehearsal,observe as observeRehearsal,report as rehearsalReport} from './rehearsal.js';
import * as R from './realm.js';
import {WorldView} from './visual.js';
import * as P from './pavilions.js';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SAVE='awe-concord-v10',PREVIOUS='awe-concord-v09',OLD='awe-first-orchard-v08';
let studio=null,rehearsal=null,placing=null;
let state=R.newRealm(),loaded=false,started=false,modal=null,keys={},near=null,view,selectedPath='thread',activity=null,pausedByTab=false,saveLock=false,releaseLock=null,saveFailure=false,pending={},sound=false,audio=null,previousFocus=null,lastHUD=0,toastTimer,discoveryTimer;
try{const raw=(localStorage.getItem(SAVE)||localStorage.getItem(PREVIOUS));if(raw&&raw.length<700000){state=R.restore(JSON.parse(raw));loaded=true;}}catch{saveFailure=true;}
try{view=new WorldView($('world'));view.reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;}catch(e){$('failure').hidden=false;$('failure').textContent=e.message;throw e;}
const held=[];function clearInput(){keys={};pending={};}
function notice(text){$('notice').textContent=text;$('notice').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('notice').classList.remove('show'),4300);}
function note(freq,d=.3,gain=.045,delay=0){if(!sound||!audio)return;const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+delay;o.frequency.value=freq;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(gain,t+.02);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+d+.03);}
function townMusic(){R.Rain.SINKS.forEach((k,i)=>{const d=state.rain.deliveries[k];if(d)note([220,330,440][i],d/6,.055,i*.22);});}
function toggleSound(){sound=!sound;if(sound){audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();townMusic();}}
function save(){if(!started||!saveLock||pausedByTab)return;try{localStorage.setItem(SAVE,JSON.stringify(R.snapshot(rehearsal?rehearsal.original:state)));}catch{if(!saveFailure)notice('This browser cannot save right now. Export your world from the journal.');saveFailure=true;}}
function change(fn,ok){if(pausedByTab){notice('This world is already active in another tab.');return false;}try{const previousWorld=state.id;fn();if(previousWorld!==state.id||state.tick<saveAt){saveAt=state.tick;lastHistory=state.revision;lastDiscovered=state.discoveries.length;lastResult=null;acc=0;clearInput();}view.rebuild(state);save();hud();if(ok)notice(ok);return true;}catch(e){notice(e.message);return false;}}
async function begin(){if(started)return;if(!loaded)state=R.newRealm(selectedPath);if(navigator.locks){navigator.locks.request('awe-concord-world',{ifAvailable:true},async lock=>{if(!lock){pausedByTab=true;$('welcome').hidden=true;openPanel('This world is open elsewhere','ONE ACTIVE COPY','<p>Close the other active game tab, then reload this page. Your saved world is preserved.</p><button id="reload" class="button primary full">Reload the world</button>','lock');bind('reload',()=>location.reload());return;}try{const latest=(localStorage.getItem(SAVE)||localStorage.getItem(PREVIOUS));if(latest){state=R.restore(JSON.parse(latest));loaded=true;}}catch{saveFailure=true;}saveLock=true;startNow();await new Promise(resolve=>releaseLock=resolve);});}else{saveLock=false;startNow();notice('This browser lacks the cross-tab save lock. You can play and export; automatic saving is disabled.');}}
function startNow(){started=true;$('welcome').hidden=true;clearInput();$('world').focus();if(saveFailure)notice('The previous snapshot could not be read. You have a fresh world; the old data was not merged.');else notice('V opens the Dream Foundry. WASD moves; E interacts. Shape something the world can use.');hud();save();}
function bind(id,fn){$(id)?.addEventListener('click',fn);}
function openPanel(title,kicker,content,type='other'){$('hud').inert=true;previousFocus=document.activeElement;modal=type;clearInput();$('panel-title').textContent=title;$('panel-kicker').textContent=kicker;$('panel-content').innerHTML=content;$('panel').hidden=false;$('scrim').hidden=false;$('interact-wrap').hidden=true;$('close').focus();}
function closePanel(){if(modal==='lock')return;if(modal==='foundry'){studio?.close();return;}$('hud').inert=false;modal=null;clearInput();$('panel').hidden=true;$('scrim').hidden=true;view.setPreview(null);if(started)$('world').focus();else if(previousFocus instanceof HTMLElement)previousFocus.focus();}
function facts(rows){return '<table class="facts">'+rows.map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')+'</table>';}
function costs(c){return Object.entries(c).map(([k,n])=>`${n} ${k}`).join(' · ');}
function waterTable(s=state.rain.storage){return facts([['Crossing · needs 6',s.bridge],['Orchard · needs 5',s.orchard],['Reeds · needs 5',s.habitat]]);}
function loomMap(plan=[]){const pts={spring:[210,22],west:[95,81],east:[320,81],bridge:[210,157],orchard:[355,157],habitat:[58,157]};return `<svg class="loom-diagram" viewBox="0 0 420 200" aria-label="The actual water network">${Object.values(state.rain.channels).map(c=>`<line x1="${pts[c.from][0]}" y1="${pts[c.from][1]}" x2="${pts[c.to][0]}" y2="${pts[c.to][1]}"/>`).join('')}${plan.map(([a,b])=>`<line class="ghost" x1="${pts[a][0]}" y1="${pts[a][1]}" x2="${pts[b][0]}" y2="${pts[b][1]}"/>`).join('')}${Object.entries(pts).map(([id,[x,y]])=>`<circle cx="${x}" cy="${y}" r="7"/><text x="${x}" y="${y+25}" text-anchor="middle">${id==='habitat'?'reeds':id}</text>`).join('')}</svg>`;}
function loom(){view.setPreview(null);openPanel('Give the rain a path','WORLDCRAFT · WEAVE & SHAPE',`<p>The crossing, orchard and reeds share one rain. Preview your changes, make them real, then release the water.</p><div id="loom-map">${loomMap()}</div>${waterTable()}<div class="row"><button id="pulse" class="button primary">Pulse the rain <kbd>F</kbd></button><button id="chord" class="button subtle">Sound a rain chord</button></div>${!Object.keys(state.rain.channels).length?'<div class="card"><h4>The Mercy Braid</h4><p>Six lasting connections, 24 fiber. Balanced rain reaches all three places equally.</p><button id="braid" class="button subtle">Preview the complete braid ↗</button></div>':''}<div class="grid-two"><div class="field"><label for="from">From</label><select id="from"><option value="spring">Wellspring</option><option value="west">West loom</option><option value="east">East loom</option></select></div><div class="field"><label for="to">To</label><select id="to"></select></div></div><div class="grid-two"><div class="field"><label for="capacity">Capacity</label><select id="capacity">${[1,2,3,4,5,6].map(n=>`<option ${n===4?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="kind">Form</label><select id="kind"><option value="installed">Lasting · fiber</option><option value="temporary">3 rains · Focus</option></select></div></div><button id="preview" class="button primary full">Preview one connection</button><div id="forecast"></div><p class="small">Your stock: ${state.rain.fiber.human} fiber · ${state.rain.focus.human} finite weaving Focus. Combat Breath is a separate regenerating meter.</p><h3>First claim on scarce water</h3><div class="field"><label for="priority">Complete allocation order</label><select id="priority">${permutations(R.Rain.SINKS).map(p=>`<option value="${p.join(',')}" ${p.join()===state.rain.priority.join()?'selected':''}>${p.join(' → ')}</option>`).join('')}</select></div><button id="recover-fiber" class="button subtle full">Exchange 2 wood for up to 6 keeper fiber</button><h3>Connections in the landscape</h3>${Object.entries(state.rain.channels).map(([k,c])=>`<div class="slot"><span>${c.from} → ${c.to}<small>${c.capacity} capacity · ${c.owner==='agent'?'Serein':'you'} · ${c.kind==='temporary'?c.remaining+' rains left':'lasting'}</small></span>${c.owner==='human'?`<button data-remove="${k}" class="text-action">${c.kind==='temporary'?'Dismiss':'Salvage '+Math.floor(c.capacity/2)}</button>`:'<span class="small">Partner-owned</span>'}</div>`).join('')||'<p class="small">No channels yet.</p>'}`,'loom');
 bind('recover-fiber',()=>{if(change(()=>R.recoverWeaving(state)))loom();});function destinations(){$('to').innerHTML=($('from').value==='spring'?['west','east']:R.Rain.SINKS).map(k=>`<option value="${k}">${k==='habitat'?'Reeds':k}</option>`).join('');}destinations();$('from').onchange=destinations;$('priority').onchange=()=>{if(change(()=>R.waterPriority(state,$('priority').value.split(','))))loom();};bind('pulse',()=>{if(change(()=>R.rainPulse(state))){townMusic();loom();}});bind('chord',()=>change(()=>R.chord(state),'The conserved rain chord is active for five seconds.'));bind('braid',()=>previewWater(R.Rain.BRAID,'installed'));bind('preview',()=>previewWater([[$('from').value,$('to').value,Number($('capacity').value)]],$('kind').value));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(change(()=>{R.Rain.removeChannel(state.rain,b.dataset.remove);R.record(state,'You salvaged a channel. Stored water remains.');}))loom();});}
function permutations(a){return a.length?a.flatMap((x,i)=>permutations(a.filter((_,j)=>j!==i)).map(p=>[x,...p])):[[]];}
function previewWater(plan,kind){try{const next=structuredClone(state.rain);for(const[a,b,n]of plan)R.Rain.channel(next,a,b,n,kind);R.Rain.pulse(next);const revision=state.revision,rainRevision=state.rain.revision,exact=JSON.stringify(plan);view.setPreview(plan);$('loom-map').innerHTML=loomMap(plan);$('forecast').innerHTML=`<div class="card"><h4>After the next ${state.rain.weather} rain</h4>${waterTable(next.storage)}<p>${plan.reduce((sum,p)=>sum+p[2],0)} ${kind==='temporary'?'Focus':'fiber'} · ${plan.length} connections. Nothing spent yet.</p><button id="accept-water" class="button primary full">Make this design real</button></div>`;bind('accept-water',()=>{if(change(()=>{if(state.revision!==revision||state.rain.revision!==rainRevision)throw Error('The world changed. Preview again.');const w=structuredClone(state.rain);for(const[a,b,n]of JSON.parse(exact))R.Rain.channel(w,a,b,n,kind);state.rain=w;R.record(state,'You made the previewed water design real.');},'The threads are real. Pulse to send water through them.')){note(523,.45);loom();}});}catch(e){notice(e.message);}}
function character(){openPanel('Your own way through','CHARACTER · INVENTORY & CRAFT',`<p>Level ${state.hero.level} ${state.hero.discipline} wayfarer · ${state.hero.xp} experience. Equipment changes real combat values.</p>${facts(R.MATERIALS.map(k=>[k,state.pack[k]]))}<h3>Supplies</h3><div class="row"><button id="use-tonic" class="button subtle">Tonic ×${state.hero.items.tonic||0} · heal 45</button><button id="use-meal" class="button subtle">Meal ×${state.hero.items.meal||0} · heal & Breath</button></div><h3>The workshop</h3>${Object.entries(R.RECIPES).map(([id,r])=>`<div class="card"><h4>${r.name} ${state.hero.equipment[id]?'· equipped':''}</h4><p>${r.text}</p><p class="small">${costs(r.cost)}</p><button data-craft="${id}" class="button subtle" ${state.hero.equipment[id]?'disabled':''}>Craft ${r.name}</button></div>`).join('')}<h3>Attack timing</h3>${facts(Object.values(R.MOVES).map(m=>[m.name,`${m.startup} / ${m.active} / ${m.recovery}`]))}<p class="small">Startup / active / recovery in 60 Hz frames. A swing hits each opponent at most once. Guard faces the threat; evade protects only its middle ten frames.</p>`,'character');bind('use-tonic',()=>{if(change(()=>R.consume(state,'tonic')))character();});bind('use-meal',()=>{if(change(()=>R.consume(state,'meal')))character();});document.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>{if(change(()=>R.craft(state,b.dataset.craft)))character();});}
function settlement(){openPanel('A place to belong','SETTLEMENT · SIX REAL PLOTS',`<p>Build on the marked plots in the village. Structures occupy space, consume materials, and unlock work.</p><div class="grid-two"><div class="field"><label for="building">Structure</label><select id="building">${Object.entries(R.BUILDINGS).map(([k,b])=>`<option value="${k}">${b.name}</option>`).join('')}</select></div><div class="field"><label for="plot">Empty plot</label><select id="plot">${R.PLOTS.filter(p=>!state.structures.some(b=>b.plot===p.id)).map(p=>`<option value="${p.id}">Plot ${p.id+1}</option>`).join('')}</select></div></div><div id="building-info" class="card"></div><button id="build" class="button primary full">Construct on this plot</button><h3>People, not a production counter</h3><p class="small">Workers travel to a finite resource, gather it, and carry it home. Each bundle consumes one food. Gardeners also need a watered orchard and a passable crossing.</p>${state.workers.map(w=>`<div class="field"><label for="worker-${w.id}">${w.name} · ${w.cargo?'carrying '+w.cargo.count+' '+w.cargo.item:w.job==='rest'?'resting':w.phase||'working'}</label><select id="worker-${w.id}" data-worker="${w.id}">${['rest','wood','stone','food'].map(j=>`<option ${w.job===j?'selected':''}>${j}</option>`).join('')}</select></div>`).join('')}<h3>Built in this world</h3>${state.structures.map(b=>`<div class="slot"><span>${R.BUILDINGS[b.type].name}</span><span>Plot ${b.plot+1}</span><button data-demolish="${b.plot}" class="text-action">Dismantle</button></div>`).join('')||'<p class="small">The first roof is still yours to raise.</p>'}`,'settlement');document.querySelectorAll('[data-demolish]').forEach(el=>el.onclick=()=>{if(change(()=>R.demolish(state,Number(el.dataset.demolish))))settlement();});function info(){const b=R.BUILDINGS[$('building').value];$('building-info').innerHTML=`<h4>${b.name}</h4><p>${b.text}</p><p class="small">${costs(b.cost)}</p>`;}info();$('building').onchange=info;bind('build',()=>{if(change(()=>R.construct(state,$('building').value,Number($('plot').value))))settlement();});document.querySelectorAll('[data-worker]').forEach(e=>e.onchange=()=>{if(change(()=>R.assign(state,e.dataset.worker,e.value)))settlement();});}
function market(){const merchant=R.LANDMARKS.find(l=>l.id==='market'),close=state.mode==='world'&&Math.hypot(state.hero.x-merchant.x,state.hero.z-merchant.z)<7;openPanel('Vey’s Exchange','A FINITE LOCAL MARKET',`<p class="quote">“Every bundle came from somewhere. Every Mark belongs to someone.”</p><p>You have ${state.rain.balances.human} Marks. The merchant holds ${state.rain.balances.keeper}. Prices respond to its stock; a quote binds the exact quantity and price.</p>${facts(R.MATERIALS.map(k=>[`${k} · stock ${state.market[k]}`,`${R.prices(state,k).ask} ask / ${R.prices(state,k).bid} bid`]))}<div class="grid-two"><div class="field"><label for="trade-item">Material</label><select id="trade-item">${R.MATERIALS.map(k=>`<option>${k}</option>`).join('')}</select></div><div class="field"><label for="trade-qty">Quantity</label><input id="trade-qty" type="number" min="1" max="20" value="1"></div></div><div class="row"><button id="quote-buy" class="button primary" ${close?'':'disabled'}>Quote a purchase</button><button id="quote-sell" class="button subtle" ${close?'':'disabled'}>Quote a sale</button></div>${!close?'<p class="small">Walk to the merchant beside the village arch to trade. Its location is marked in the Atlas.</p>':''}<div id="trade-quote"></div><p class="small">This market has one finite merchant counterparty. A player-to-player auction house and online order book are not running here.</p>`,'market');for(const side of['buy','sell'])bind('quote-'+side,()=>{try{const q=R.quote(state,$('trade-item').value,side,Number($('trade-qty').value));$('trade-quote').innerHTML=`<div class="card"><h4>${side==='buy'?'Buy':'Sell'} ${q.qty} ${q.item}</h4><p>${q.unit} Marks each · ${q.total} total</p><button id="trade-accept" class="button primary full">Accept this exact quote</button></div>`;bind('trade-accept',()=>{if(change(()=>R.trade(state,q)))market();});}catch(e){notice(e.message);}});}
function quests(){openPanel('The Unwritten','QUESTS · ACTUAL CONSEQUENCES',`<p>These chapters complete when you do the work in the world. Experience is personal progression; it creates no money.</p>${R.QUESTS.map(q=>`<div class="card ${state.completed.includes(q.id)?'complete':''}"><h4>${state.completed.includes(q.id)?'✓ ':''}${q.title}</h4><p>${q.text}</p><p class="small">${state.completed.includes(q.id)?'Remembered · 25 experience awarded once':'Open · 25 experience'}</p></div>`).join('')}<button id="quest-loom" class="button primary full">Tend the living crossing</button>`,'quests');bind('quest-loom',loom);}
function companion(){openPanel('Serein & the Lumenling','COMPANIONS · INVITATION & MEMORY',`<p class="quote">“Leave a thread for yourself. I can help with what remains.”</p><p>Serein proposes legal water repairs using its own ${state.rain.fiber.agent} fiber. Its exact viewed plan is bound to this world and permission epoch.</p><label class="check"><input id="grant" type="checkbox" ${state.rain.grant.enabled?'checked':''}>Invite Serein to propose and build</label><label class="check"><input id="reserve" type="checkbox" ${state.rain.reserveBridge?'checked':''}>Reserve both bridge inlets for me</label><button id="ask" class="button primary full" ${state.rain.grant.enabled?'':'disabled'}>Ask for an inspectable proposal</button><div id="proposal"></div><h3>The Lumenling · bond ${state.pet.bond}/5</h3><p>${state.pet.memory.length} distinct events remembered. Its memories grow through discoveries and completed chapters, not time spent idle.</p><div class="row"><button id="pet-follow" class="button subtle">Follow my footsteps</button><button id="pet-stay" class="button subtle">Wait here</button><button id="pet-music" class="button subtle">Hear the world’s memory</button></div><p class="small">Serein and combat opponents use disclosed scripted decision rules. There is no connected language-model service in this build.</p>`,'agent');$('grant').onchange=e=>{if(change(()=>R.agentGrant(state,e.target.checked)))companion();};$('reserve').onchange=e=>{if(change(()=>{R.Rain.reserve(state.rain,e.target.checked);R.record(state,'Updated the bridge contribution reservation.');}))companion();};bind('ask',()=>{try{const p=R.agentProposal(state);$('proposal').innerHTML=`<div class="card"><h4>Serein’s proposed repair</h4><p>${p.plan.map(([a,b,c])=>`${a} → ${b}, capacity ${c}`).join('<br>')}</p>${waterTable(p.forecast)}<button id="accept-agent" class="button primary full">Accept only this viewed plan</button></div>`;bind('accept-agent',()=>{if(change(()=>R.acceptAgent(state,p),'Serein made your approved repair.'))companion();});}catch(e){notice(e.message);}});bind('pet-follow',()=>change(()=>{state.pet.mode='follow';R.record(state,'You asked the Lumenling to follow.');},'The Lumenling will follow legal paths.'));bind('pet-stay',()=>change(()=>{state.pet.mode='stay';R.record(state,'You asked the Lumenling to wait.');},'The Lumenling waits here.'));bind('pet-music',()=>{if(!sound)toggleSound();else townMusic();});}
function journal(){if(rehearsal){notice('Return from the rehearsal before importing or exporting a world.');return;}openPanel('What the world remembers','EVENTS · OWNERSHIP · EXPORT',`<div class="row"><button id="export" class="button primary">Export your world ↓</button><button id="import-button" class="button subtle">Import a world ↑</button><input type="file" id="import" accept="application/json" hidden></div><p class="small">Import replaces a snapshot; it never merges assets. Activities end at their saved world entrance on reload.</p>${facts([['Vey’s wagon',state.rain.cargo.status],['Food lot · owner',`4 · ${state.rain.cargo.owner}`],['Reserved commission',`${state.rain.escrow} Marks`],['Carrier received',`${state.rain.balances.carrier} Marks`],['Total money',`${R.Rain.ledger(state.rain).money} / 50`],['Water accounting residual',R.Rain.ledger(state.rain).water],['Material accounting',Object.values(R.materialLedger(state)).every(n=>n===0)?'Balanced':'Needs inspection']])}<h3>Recent events</h3>${[...state.history].reverse().slice(0,70).map(e=>`<div class="history"><small>EVENT ${e.id} · ${Math.floor(e.tick/60)} active seconds</small><p>${esc(e.text)}</p></div>`).join('')}<p class="small">The most recent 300 events are retained. A local snapshot is not a full replay proof or an on-chain record.</p><a class="audit-link" href="./audit.html" target="_blank" rel="noopener">Read the complete project audit ↗</a>`,'journal');bind('import-button',()=>$('import').click());bind('export',()=>{const b=new Blob([JSON.stringify(R.snapshot(rehearsal?rehearsal.original:state),null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='AWE-Dream-Foundry-world.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1500);});$('import').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>700000){notice('That snapshot is too large.');return;}try{const candidate=R.restore(JSON.parse(await f.text()));openPanel('Replace this local world?','IMPORT A SNAPSHOT',`<p>This will replace your current world with a validated saved world. Export first if you want to keep both.</p><button id="confirm-import" class="button primary full">Replace this world</button>`,'import');bind('confirm-import',()=>{if(change(()=>{state=candidate;})){closePanel();notice('World restored. No resources were merged.');}});}catch(err){notice('Import rejected: '+err.message);}};}
function atlas(){view.atlas=true;openPanel('The First Orchard','ATLAS · THE SAME INHABITED WORLD',`<p>The overhead view shows your actual body, routes, enemies and buildings. Choose a place to mark its direction, then walk there.</p>${R.LANDMARKS.map(l=>`<div class="slot"><span>${state.discoveries.includes(l.id)?'✧ ':''}${l.name}<small>${l.kind}</small></span><button data-track="${l.id}" class="text-action">Track ↗</button></div>`).join('')}<button id="body-view" class="button subtle full">Return to third person</button>`,'atlas');document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>{tracked=b.dataset.track;closePanel();notice('Follow the marked landmark. The Atlas never teleports your body.');});bind('body-view',()=>{view.atlas=false;closePanel();});}
function settings(){openPanel('Your world, your pace','SETTINGS & CONTROLS',`<p>V opens the Dream Foundry. T uses your attuned creation. WASD moves, drag or right-drag looks around, Space jumps, Shift runs. Click or 1 strikes; 2 reaches; 3 shoots; 4 releases Gale Break. Hold C to guard; R evades; E interacts; Q opens worldcraft; F releases rain.</p><label class="check"><input id="sound" type="checkbox" ${sound?'checked':''}>World sound</label><label class="check"><input id="motion" type="checkbox" ${view.reduced?'checked':''}>Reduced ambient motion</label><label class="check"><input id="auto-rain" type="checkbox" ${state.options.autoRain?'checked':''}>Rain every 20 active seconds</label><div class="field"><label for="weather">Weather for the next rain</label><select id="weather">${['balanced','drought','storm'].map(w=>`<option ${state.rain.weather===w?'selected':''}>${w}</option>`).join('')}</select></div><p class="small">All panels, pavilion boards and hidden tabs pause simulation. No offline catch-up. Auto-rain is optional and off by default.</p><h3>World menu</h3><button id="settings-create" class="button primary full">Open the Dream Foundry</button><div class="row"><button id="settings-market" class="button subtle">Exchange</button><button id="settings-journal" class="button subtle">World journal</button><button id="settings-games" class="button subtle">Worldheart games</button></div><h3>What this build is</h3><p>This is an interconnected local browser game: combat, a multi-phase PvE encounter, bot CTF, local two-player duels, building, production, trading, companion memory and pavilion games.</p><p class="small">Online multiplayer, a live LLM service, a production MMO backend and crypto settlement remain unimplemented. No wallet, token sale or financial return is involved.</p><a href="./vision.html" target="_blank" rel="noopener" class="audit-link">Creation guide, whole-game plan and evidence ↗</a><a href="./audit.html" target="_blank" rel="noopener" class="audit-link">Historical accountability audit ↗</a><button id="fresh" class="button subtle full">Begin a fresh world</button><div id="reset-confirm"></div>`,'settings');$('sound').onchange=toggleSound;$('motion').onchange=e=>view.reduced=e.target.checked;$('auto-rain').onchange=e=>change(()=>{state.options.autoRain=e.target.checked;R.record(state,'Automatic rain '+(e.target.checked?'enabled':'disabled')+'.');});$('weather').onchange=e=>change(()=>{R.Rain.setWeather(state.rain,e.target.value);R.record(state,'Weather changed to '+e.target.value+'.');});bind('settings-create',()=>openFoundry());bind('settings-market',market);bind('settings-journal',journal);bind('settings-games',games);bind('fresh',()=>{if(rehearsal){notice('Return from the rehearsal before replacing your world.');return;}$('reset-confirm').innerHTML='<div class="card"><p>This replaces your device’s saved world. Export your world from the journal to keep its record first.</p><button id="fresh-confirm" class="button primary full">Replace with a fresh world</button></div>';bind('fresh-confirm',()=>{if(change(()=>{state=R.newRealm(selectedPath);})){closePanel();view.atlas=false;notice('A fresh world. A new story.');}});});}
function games(){const close=Math.hypot(state.hero.x-24,state.hero.z-15)<6&&state.mode==='world';openPanel('Games within the world','THE BELL PAVILION',`<p>The pavilion holds games of attention and connection. Your body remains at its real entrance; no money or items are created.</p><div class="card"><h4>Raincatch</h4><p>Catch amber notes. Let pale rain pass. Move the bowl with A/D, arrows or touch. Forty-five seconds.</p><p class="small">Best: ${state.bests.raincatch} notes</p><button id="play-rain" class="button primary" ${close?'':'disabled'}>Play Raincatch</button></div><div class="card"><h4>Loom Table</h4><p>Place and rotate connected tiles. Amber connects west to east; Teal connects north to south. Everyone can use every tile. A move completing both routes is a draw.</p><div class="field"><label for="loom-mode">Opponent</label><select id="loom-mode"><option value="bot">Disclosed scripted opponent</option><option value="human">Two humans · take turns</option></select></div><button id="play-loom" class="button primary" ${close?'':'disabled'}>Sit at the Loom Table</button></div>${!close?'<p class="small">Walk to the bell pavilion in the eastern village to play. It is marked on the Atlas.</p>':''}<h3>Out in the landscape</h3><p>Find the Singing Range for a physical projectile challenge, the Tension Court for a local duel, and Lanternwake Gate for team capture-the-flag.</p>`,'games');bind('play-rain',()=>startPavilion('raincatch'));bind('play-loom',()=>startPavilion('loom',$('loom-mode').value));}
function activityPanel(mode){const l=R.LANDMARKS.find(l=>l.kind===mode),close=state.mode==='world'&&Math.hypot(state.hero.x-l.x,state.hero.z-l.z)<6;const c={boss:['The Root Warden','A MULTI-PHASE PVE ENCOUNTER','Learn its sweep, evade marked ground, survive its rootlings and find the opening after a volley. This is one local boss encounter, not a multiplayer raid.'],ctf:['Lanternwake','CAPTURE THE FLAG · LOCAL EXHIBITION','You and one scripted ally face two scripted rivals. Take their lantern home while yours is still there. Three captures or four active minutes. Flags drop on defeat and return after fifteen seconds.'],duel:['The Tension Court','TIMING, SPACE & COUNTERPLAY','Practice against a disclosed bot, or invite someone beside you for a real local two-player duel. Player one: WASD, 1/2/3/4, C guard, R evade, left Shift run. Player two: arrows, K/L/O/U, P guard, Enter evade, right Shift run.']}[mode];openPanel(c[0],c[1],`<p>${c[2]}</p>${mode==='boss'?'<p class="small">Red ground marks announce a future attack. Press R to evade and face the Warden while holding C to guard. Recoveries are real openings.</p>':''}${mode==='duel'?'<label class="check"><input id="local2" type="checkbox">Two humans on this keyboard</label>':''}<button id="enter-activity" class="button primary full" ${close?'':'disabled'}>${mode==='boss'?'Enter the clearing':mode==='ctf'?'Enter Lanternwake':'Begin a duel'}</button>${!close?'<p class="small">Walk to this gate before entering.</p>':''}${mode==='boss'&&state.bossDefeated?`<button id="cache" class="button subtle full" ${state.cacheClaimed?'disabled':''}>${state.cacheClaimed?'The finite cache was already claimed':'Claim the Warden cache · 3 crystals'}</button>`:''}<p class="small">This is a separate local activity. Your saved world position is retained. Leaving returns the same inventory; exhibition projectiles and health do not export.</p>`,'activity');bind('enter-activity',()=>{const local2=$('local2')?.checked||false;if(change(()=>R.enterActivity(state,mode,local2))){closePanel();view.atlas=false;notice(mode==='ctf'?'Take the teal flag. Bring it to the amber base.':mode==='duel'?'The duel begins. Spacing matters.':'The Warden is waiting. Watch the ground.');}});bind('cache',()=>{if(change(()=>R.claimCache(state)))activityPanel(mode);});}
let tracked=null;
function interact(){if(state.mode!=='world'){if(state.mode==='boss'&&state.bossDefeated&&!state.cacheClaimed&&Math.hypot(state.hero.x-75,state.hero.z+47)<5){change(()=>R.claimCache(state),'The finite cache is yours.');return;}exitActivityPanel();return;}if(!near){notice('Approach a person, resource or landmark, then press E.');return;}if(near.creation){creationDetails(near.id);return;}if(near.resource){change(()=>R.gather(state,near.id),'Gathered one '+near.item+'.');return;}const map={loom,market,settlement,games,agent:companion,quests,journal,pet:companion,range:rangePanel,boss:()=>activityPanel('boss'),ctf:()=>activityPanel('ctf'),duel:()=>activityPanel('duel')};map[near.kind]?.();}
function rangePanel(){openPanel('The Singing Range','PHYSICAL PROJECTILES · EIGHT TARGETS','<p>Eight moving glass bells stand beyond the range. Face them and fire Glass Note with 3. Shots collide with the nearest target or obstacle.</p><p>Finish in sixty active seconds. Each hit scores ten; completing all eight adds the remaining seconds. This is a personal record, not a network leaderboard.</p><button id="start-range" class="button primary full">Begin the range challenge</button>','range');bind('start-range',()=>{if(change(()=>R.startRange(state))){closePanel();state.hero.angle=0;view.yaw=Math.PI;notice('Face the bells and press 3. A/D moves your aim across them.');}});}
function exitActivityPanel(){const a=state.activity,score=a?.winner?`Result: ${a.winner}.`:'The activity is still in progress.';openPanel('Return to your world','ACTIVITY EXIT',`<p>${score}</p><p>Your inventory stays with you. Exhibition health and projectiles are discarded.</p>${state.mode==='boss'&&state.bossDefeated&&!state.cacheClaimed?'<button id="claim-end" class="button primary full">Claim the finite Warden cache</button>':''}<button id="leave-activity" class="button primary full">Return to the gate</button><button id="keep-playing" class="button subtle full">Keep playing</button>`,'exit');bind('claim-end',()=>{if(change(()=>R.claimCache(state)))exitActivityPanel();});bind('leave-activity',()=>{if(change(()=>R.leaveActivity(state))){closePanel();notice('You returned to your world.');}});bind('keep-playing',closePanel);}
function startPavilion(kind,mode='bot'){if(state.mode!=='world'||Math.hypot(state.hero.x-24,state.hero.z-15)>6)return;closePanel();clearInput();activity={kind,game:kind==='loom'?P.newLoom():P.newRaincatch(),committed:false};activity.game.mode=mode;$('pavilion').hidden=false;$('hud').hidden=true;$('rain-canvas').hidden=kind!=='raincatch';$('loom-board-wrap').hidden=kind!=='loom';$('pavilion-result').hidden=true;$('pavilion-title').textContent=kind==='loom'?'Loom Table':'Raincatch';$('pavilion-help').textContent=kind==='loom'?'Amber: west → east. Teal: north → south. Rotate, choose, connect.':'Catch amber notes. Let pale rain pass. Move with A / D or drag.';$('hud').inert=true;$('leave-pavilion').focus();if(kind==='loom')drawLoom();}
function leavePavilion(){activity=null;$('hud').inert=false;$('pavilion').hidden=true;$('hud').hidden=false;clearInput();$('world').focus();save();}
function pavilionResult(score,text){if(!activity||activity.committed)return;activity.committed=true;change(()=>R.finishPavilion(state,activity.kind,score));$('pavilion-result').hidden=false;$('pavilion-result').innerHTML=`<p class="eyebrow">A MOMENT REMEMBERED</p><h2>${text}</h2><p>Local result. No tradable rewards.</p><button id="pav-again" class="button primary">Play again</button><button id="pav-leave" class="button subtle">Return to the world</button>`;const kind=activity.kind,mode=activity.game.mode;$('pav-again').focus();bind('pav-again',()=>startPavilion(kind,mode));bind('pav-leave',leavePavilion);}
function drawLoom(){const g=activity.game;$('loom-controls').innerHTML=Object.keys(P.SHAPES).map(k=>`<button class="button ${g.selection===k?'primary':'subtle'}" data-shape="${k}">${k}</button>`).join('')+'<button id="rotate" class="button subtle">Rotate ↻</button>';$('loom-board').innerHTML=g.board.map((p,i)=>{const dirs=p?P.ports(p):[],ends=[[50,4],[96,50],[50,96],[4,50]];return `<button data-tile="${i}" class="${p?.owner===1?'teal':''} ${g.path?.includes(i)?'winning':''}" aria-label="Row ${Math.floor(i/5)+1}, column ${i%5+1}${p?', '+p.shape:', empty'}" ${p||g.ended?'disabled':''}><svg viewBox="0 0 100 100">${dirs.map(d=>`<path d="M50 50L${ends[d][0]} ${ends[d][1]}"/>`).join('')}</svg></button>`;}).join('');$('loom-status').textContent=g.ended?g.winner==='draw'?'Both or neither route: a draw.':(g.winner===0?'Amber':'Teal')+' connected the world.':`${g.turn===0?'Amber':'Teal'} to place · ${g.selection} · rotation ${g.rotation*90}°`;$('pavilion-score').textContent='Move '+g.moves+' / 25';document.querySelectorAll('[data-shape]').forEach(b=>b.onclick=()=>{g.selection=b.dataset.shape;drawLoom();});bind('rotate',()=>{g.rotation=(g.rotation+1)%4;drawLoom();});document.querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>{if(g.mode==='bot'&&g.turn===1)return;if(P.placeLoom(g,Number(b.dataset.tile))){if(g.mode==='bot'&&!g.ended)P.loomBot(g);drawLoom();if(g.ended)pavilionResult(g.winner===0?100:g.winner==='draw'?50:25,g.winner==='draw'?'A shared ending':g.winner===0?'Amber connects':'Teal connects');}});}
function rainFrame(dt){const g=activity.game,c=$('rain-canvas'),ctx=c.getContext('2d'),w=innerWidth,h=innerHeight;if(c.width!==w||c.height!==h){c.width=w;c.height=h;}const old=g.score;P.tickRaincatch(g,dt,(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0));if(g.score>old)note([440,523,659,784][g.score%4],.18);ctx.clearRect(0,0,w,h);ctx.strokeStyle='#c0daca16';for(let i=1;i<9;i++){ctx.beginPath();ctx.moveTo(w*i/9,h*.18);ctx.lineTo(w*i/9,h*.85);ctx.stroke();}for(const n of g.notes){ctx.fillStyle=n.gold?'#efd18f':'#9fcbd1';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=n.gold?15:3;ctx.beginPath();ctx.ellipse(n.x*w,n.y*h,n.gold?6:3,n.gold?8:11,0,0,7);ctx.fill();}ctx.shadowBlur=0;ctx.strokeStyle='#edd3a1';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(g.bowl*w,h*.82,w*.045,14,0,0,Math.PI);ctx.stroke();$('pavilion-score').textContent=`${g.score} notes · ${Math.max(0,Math.ceil(45-g.time))} seconds`;if(g.done)pavilionResult(g.score,g.score+' notes caught');}
function hud(){const h=state.hero,custom=R.Creation.activeMove(state);$('creation-power').hidden=!custom;if(custom)$('creation-power').querySelector('span').textContent=custom.name;$('marks').textContent=state.rain.balances.human;$('hero-name').textContent=h.discipline==='stone'?'Stonekeeper':h.discipline==='gale'?'Galeweaver':'Threadwalker';$('hero-level').textContent=`Level ${h.level} · ${h.xp} experience`;$('health').max=h.maxHp;$('health').value=h.hp;$('health-value').textContent=Math.ceil(h.hp);$('breath').value=h.breath;$('breath-value').textContent=Math.floor(h.breath);$('materials').innerHTML=R.MATERIALS.filter(k=>state.pack[k]>0).map(k=>`<span><b>${state.pack[k]}</b>${k}</span>`).join('');$('mode-label').textContent=state.mode==='world'?`${state.rain.weather.toUpperCase()} · RAIN ${state.rain.pulse}`:state.mode==='ctf'?'YOU + 1 BOT · VS 2 BOTS':state.mode==='duel'?(state.activity.local2?'LOCAL TWO-PLAYER DUEL':'DUEL · SCRIPTED OPPONENT'):'LOCAL PVE ENCOUNTER';$('area-label').textContent=state.mode==='world'?(h.z<-19?'THE FAR ORCHARD':'THE FIRST ORCHARD'):state.mode==='boss'?'THE ROOT WARDEN':state.mode==='ctf'?'LANTERNWAKE':'THE TENSION COURT';$('map-caption').textContent=state.mode==='world'?(h.z<-19?'THE FAR BANK':'THE NEAR BANK'):state.mode.toUpperCase();$('combat-state').textContent=h.dead?'Your safety thread is returning…':h.action?`${h.action.move?.name||R.MOVES[h.action.kind]?.name||'Stagger'} · ${h.action.frame} frames`:h.guard?'Guarding · face the incoming attack':state.range&&!state.range.finished?`Range · ${state.range.hits}/8 · ${Math.max(0,60-Math.floor((state.tick-state.range.start)/60))}s`:'C guard · R evade · E interact';let q=R.QUESTS.find(q=>!state.completed.includes(q.id));if(state.mode!=='world'){$('objective-title').textContent=state.mode==='boss'?'Read the warning.':state.mode==='ctf'?'Carry their light home.':'Spacing is your opening.';$('objective-copy').textContent=state.mode==='boss'?'Red ground announces danger. Evade, guard and attack during recovery.':state.mode==='ctf'?'Your flag must be home to capture theirs. Defeat drops the carried flag.':'1 / 2 strikes. 3 shoots. C guards toward the threat. R evades.';$('objective-action').textContent='Leave this activity ↗';}else{$('objective-title').textContent=q?q.title:'The world is still yours.';$('objective-copy').textContent=q?q.text:'Explore another path, tend your settlement, or begin a different experiment.';$('objective-action').textContent=q?.id==='creation'?'Open the Dream Foundry ↗':q?.id==='crossing'?'Open the water loom ↗':'Read your chapters ↗';}$('mode-score').hidden=state.mode!=='ctf';if(state.mode==='ctf'){const a=state.activity;$('mode-score').textContent=`AMBER ${a.scores.amber} : ${a.scores.teal} TEAL · ${Math.max(0,240-Math.floor(a.elapsed/60))}s${a.winner?' · '+a.winner.toUpperCase():''}`;}if(state.mode==='trial'){const a=state.activity;$('area-label').textContent=a.blueprint.name;$('mode-label').textContent='YOUR AUTHORED TRIAL';$('objective-title').textContent='A path you imagined.';$('objective-copy').textContent=a.blueprint.order==='sequence'?'Touch the glowing sigils in order.':'Find every sigil in any order.';$('mode-score').hidden=false;$('mode-score').textContent=a.touched.length+' / '+a.blueprint.course.length+' · '+Math.max(0,a.blueprint.seconds-Math.floor(a.elapsed/60))+'s'+(a.winner?' · '+a.winner:'');}const boss=state.enemies.find(e=>e.boss&&e.hp>0);$('boss-bar').hidden=!boss||state.mode!=='boss';if(boss&&state.mode==='boss'){$('boss-bar').querySelector('i').style.width=boss.hp/boss.maxHp*100+'%';$('boss-bar').querySelector('small').textContent=`${boss.hp} / ${boss.maxHp} · Phase ${boss.phase}`;}}
const labelEls=new Map();
function labels(){near=null;let best=4.5,entries=[];if(state.mode==='world'){entries=[...state.creation.instances.filter(e=>e.id!==state.creation.equipped).map(e=>({id:e.id,name:e.blueprint.name,x:e.x,z:e.z,creation:true})),...R.LANDMARKS,...R.RESOURCES.map(r=>({...r,resource:true}))];for(const n of entries){const d=Math.hypot(state.hero.x-n.x,state.hero.z-n.z);if(d<best){best=d;near=n;}}}entries.push(...state.enemies.filter(e=>e.hp>0&&!e.dead).map(e=>({id:e.id,name:e.boss?'Root Warden':e.team==='amber'?'Mira · ally bot':e.team==='teal'?(state.activity?.local2?'Player Two':'Rival · bot'):'Gloomling',x:e.x,z:e.z,y:e.boss?7.7:2.8,hp:e.hp,maxHp:e.maxHp,enemy:true})));const active=new Set();for(const n of entries){const d=Math.hypot(state.hero.x-n.x,state.hero.z-n.z),p=view.project(n.x,n.y||3.1,n.z),show=started&&!modal&&!activity&&p.visible&&(view.atlas||d<18||tracked===n.id);let el=labelEls.get(n.id);if(!el){el=document.createElement('div');el.className='world-label';$('world-labels').append(el);labelEls.set(n.id,el);}active.add(n.id);el.hidden=!show;if(show){el.innerHTML=`<i>${n.enemy?'':n.resource?'◇':tracked===n.id?'◆':'⌑'}</i>${esc(n.name)}${n.enemy?`<span class="hp"><b style="width:${n.hp/n.maxHp*100}%"></b></span>`:n.resource?'<small>GATHER · E</small>':''}`;el.style.left=p.x+'px';el.style.top=p.y+'px';}}for(const[id,el]of labelEls)if(!active.has(id))el.hidden=true;const prompt=state.mode!=='world'?(state.mode==='boss'&&state.bossDefeated&&!state.cacheClaimed&&Math.hypot(state.hero.x-75,state.hero.z+47)<5?'Open the Warden cache':'Return to your world'):near?(near.resource?'Gather '+near.item:near.name):null;$('interact-wrap').hidden=!prompt||!!modal||!!activity||!started;if(prompt)$('interact').querySelector('span').textContent=prompt;}
function dispatchPanel(name){({character,quests,settlement,agent:companion,atlas,settings,loom,market,journal})[name]?.();}
const toInput=()=>{const forward=(keys.w?1:0)-(keys.s?1:0),side=(keys.d?1:0)-(keys.a?1:0);const a=view.yaw,move=[side*Math.cos(a)-forward*Math.sin(a),-side*Math.sin(a)-forward*Math.cos(a)];const input={move,run:!!keys.touchRun||!!keys.shiftleft||state.mode!=='duel'&&!!keys.shiftright,guard:!!keys.c||!!keys.touchGuard,aim:pending.attack?view.yaw+Math.PI:undefined,...pending};if(state.mode==='duel'&&state.activity.local2){input.p2={move:[(keys.arrowright?1:0)-(keys.arrowleft?1:0),(keys.arrowdown?1:0)-(keys.arrowup?1:0)],run:!!keys.shiftright,guard:!!keys.p,attack:keys.u?'gale':keys.k?'palm':keys.l?'reach':keys.o?'note':undefined,dodge:!!keys.enter};}else{const f=(keys.arrowup?1:0)-(keys.arrowdown?1:0),x=(keys.arrowright?1:0)-(keys.arrowleft?1:0);if(f||x)input.move=[x*Math.cos(a)-f*Math.sin(a),-x*Math.sin(a)-f*Math.cos(a)];}pending={};return input;};
let last=performance.now()/1000,acc=0,saveAt=0,lastHistory=state.revision,lastDiscovered=state.discoveries.length,lastResult=null;
function frame(ms){const t=ms/1000,dt=Math.min(.1,Math.max(0,t-last));last=t;if(!document.hidden){if(activity){if(activity.kind==='raincatch')rainFrame(dt);}else{if(started&&!modal&&!pausedByTab){acc+=dt;for(let count=0;acc>=1/60&&count<6;count++){const input=toInput();const oldx=state.hero.x,oldz=state.hero.z;R.tick(state,input);for(const tone of state.creation.notes)note(220*Math.pow(2,tone.pitch/12),.35,.025);if(rehearsal){observeRehearsal(rehearsal.session);}state.hero.walk=Math.hypot(state.hero.x-oldx,state.hero.z-oldz)>.001?1:0;acc-=1/60;}if(state.discoveries.length>lastDiscovered){const id=state.discoveries.at(-1),l=R.LANDMARKS.find(l=>l.id===id);if(l){$('discovery').hidden=false;$('discovery').querySelector('h2').textContent=l.name;clearTimeout(discoveryTimer);discoveryTimer=setTimeout(()=>$('discovery').hidden=true,3200);note(660,.4);}lastDiscovered=state.discoveries.length;}if(state.activity?.winner&&lastResult!==state.activity.winner){lastResult=state.activity.winner;notice('Activity complete: '+state.activity.winner+'. Press E to return.');}if(!state.activity)lastResult=null;if(state.tick-saveAt>=180){save();saveAt=state.tick;}if(state.revision!==lastHistory){const e=state.history.at(-1);if(['quest','boss','ctf','production'].includes(e?.kind))notice(e.text);lastHistory=state.revision;}}else acc=0;view.render(state,t,dt,!!modal||!started);labels();if(t-lastHUD>.12){hud();view.map($('map'),state);lastHUD=t;}}}requestAnimationFrame(frame);}
function fire(kind){if(!started||modal||activity||pausedByTab)return;pending.attack=kind;pending.aim=view.yaw+Math.PI;}
function jump(){if(started&&!modal&&!activity)pending.jump=true;}
function pulse(){if(started&&!modal&&!activity&&state.mode==='world'){if(change(()=>R.rainPulse(state))){townMusic();notice('Rain moved through the accepted channels.');}}}
function trapTab(e,container){const all=[...container.querySelectorAll('button:not([disabled]),a[href],input:not([hidden]),select')].filter(e=>e.offsetParent!==null);if(!all.length)return;const first=all[0],last=all.at(-1);if(!all.includes(document.activeElement)){e.preventDefault();(e.shiftKey?last:first).focus();return;}if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase(),native=e.target.closest('button,input,select,a,textarea');if(modal){if(e.key==='Escape')closePanel();if(e.key==='Tab')trapTab(e,modal==='foundry'?$('foundry'):$('panel'));return;}if(!$('welcome').hidden){if(e.key==='Tab')trapTab(e,$('welcome'));return;}if(placing&&['e','r','escape'].includes(k)){e.preventDefault();if(k==='e')commitCreation();if(k==='r')rotateCreation();if(k==='escape')cancelCreation();return;}if(activity&&e.key==='Tab'){trapTab(e,$('pavilion'));return;}if(e.key==='Escape'){if(activity)leavePavilion();else if(state.mode!=='world')exitActivityPanel();else settings();return;}if(native&&!activity&&(e.target.matches('input,select,textarea')||k===' '||k==='enter'))return;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=true;if(e.code==='ShiftLeft')keys.shiftleft=true;if(e.code==='ShiftRight')keys.shiftright=true;if(e.repeat||activity)return;if(k===' ')jump();if('1234'.includes(k))fire({1:'palm',2:'reach',3:'note',4:'gale'}[k]);if(k==='r')pending.dodge=true;if(k==='e')interact();if(k==='q')loom();if(k==='v')openFoundry();if(k==='t')fire('creation');if(k==='f')pulse();if(k==='b')settlement();if(k==='i')character();if(k==='j')quests();if(k==='m'){view.atlas=!view.atlas;notice(view.atlas?'Atlas lens. This is the same world and body.':'Back in your own footsteps.');}});
window.addEventListener('keyup',e=>{delete keys[e.key.toLowerCase()];if(e.code==='ShiftLeft')delete keys.shiftleft;if(e.code==='ShiftRight')delete keys.shiftright;});window.addEventListener('blur',clearInput);document.addEventListener('visibilitychange',()=>{clearInput();acc=0;last=performance.now()/1000;if(document.hidden)save();});window.addEventListener('pagehide',()=>{save();releaseLock?.();saveLock=false;});
window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});
window.addEventListener('storage',e=>{if(e.key!==SAVE||!e.newValue||saveLock)return;if(!started){try{state=R.restore(JSON.parse(e.newValue));loaded=true;$('continue').hidden=false;$('begin').hidden=true;$('path-choices').hidden=true;}catch{}}else{pausedByTab=true;clearInput();notice('Another tab saved this world. Reload to use its current snapshot.');}});
let drag=null;$('world').addEventListener('contextmenu',e=>e.preventDefault());$('world').addEventListener('pointerdown',e=>{if(!started||modal||activity)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,total:0,button:e.button};$('world').setPointerCapture(e.pointerId);$('world').focus();});$('world').addEventListener('pointermove',e=>{if(placing&&!drag){const p=view.groundPoint(e.clientX,e.clientY);if(p){placing.x=p.x;placing.z=p.z;updatePlacement();}}if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.total+=Math.abs(dx)+Math.abs(dy);view.yaw-=dx*.005;view.pitch=Math.max(.1,Math.min(1.1,view.pitch+dy*.004));drag.x=e.clientX;drag.y=e.clientY;});$('world').addEventListener('pointerup',e=>{if(drag&&drag.total<6&&drag.button===0){if(placing){const p=view.groundPoint(e.clientX,e.clientY);if(p){placing.x=p.x;placing.z=p.z;}commitCreation();}else fire('palm');}drag=null;});$('world').addEventListener('pointercancel',()=>drag=null);$('world').addEventListener('wheel',e=>{e.preventDefault();view.distance=Math.max(5,Math.min(24,view.distance+e.deltaY*.015));},{passive:false});
for(const el of document.querySelectorAll('[data-move]')){el.onpointerdown=e=>{e.preventDefault();keys[el.dataset.move]=true;el.setPointerCapture(e.pointerId);};for(const t of['pointerup','pointercancel','lostpointercapture'])el.addEventListener(t,()=>delete keys[el.dataset.move]);}
$('touch-guard').onpointerdown=e=>{keys.touchGuard=true;e.target.setPointerCapture(e.pointerId);};for(const t of['pointerup','pointercancel','lostpointercapture'])$('touch-guard').addEventListener(t,()=>delete keys.touchGuard);
let rainDrag=false;$('rain-canvas').onpointerdown=e=>{rainDrag=true;e.target.setPointerCapture(e.pointerId);if(activity)activity.game.bowl=Math.max(.06,Math.min(.94,e.clientX/innerWidth));};$('rain-canvas').onpointermove=e=>{if(rainDrag&&activity)activity.game.bowl=Math.max(.06,Math.min(.94,e.clientX/innerWidth));};$('rain-canvas').onpointerup=()=>rainDrag=false;$('rain-canvas').onpointercancel=()=>rainDrag=false;
