// Creation authoring, placement, and disposable play rehearsal share the same runtime.
function openFoundry(blueprint=null){
 if(rehearsal){notice('Return from the living rehearsal before editing the next variation.');return;}
 if(!started||state.mode!=='world'){notice('Enter your world before opening the Foundry.');return;}
 if(placing)cancelCreation();if(modal)closePanel();
 if(!studio)try{studio=new CreationStudio($('foundry'),{
  world:()=>state,
  close:()=>{modal=null;clearInput();$('hud').inert=false;$('world').focus();},
  save:b=>{let saved;if(!change(()=>{saved=R.Creation.saveDraft(state,b);R.record(state,'Saved blueprint '+saved.name+'.','creation');}))throw Error('The blueprint could not be saved.');return saved;},
  removeDraft:id=>change(()=>{state.creation.drafts=state.creation.drafts.filter(b=>b.id!==id);R.record(state,'Removed a blueprint recipe; its existing instances remain.','creation');}),
  place:startCreationPlacement,rehearse:startRehearsal,inspect:creationDetails,
  experiment:r=>change(()=>R.Creation.remember(state,`Experiment · ${r.name}: ${r.damage} damage, ${r.healing} healing, ${r.deliveries} deliveries, ${r.notes} notes. ${r.trialResult||'30-second bounded policy'}.`)),
  agentGrant:on=>change(()=>{state.creation.grants.agent=on;if(!on)state.creation.proposals=[];R.Creation.remember(state,on?'Invited local agent blueprint proposals.':'Withdrew local agent proposal permission.');})
 });}catch(e){notice(e.message);return;}
 modal='foundry';clearInput();$('hud').inert=true;studio.open(blueprint);
}
function startCreationPlacement(b){
 if(state.mode!=='world')throw Error('Return to the world to place a creation.');
 const exact=R.Creation.compile(b).blueprint;studio?.close();const a=view.yaw+Math.PI;
 placing={blueprint:exact,x:state.hero.x+Math.sin(a)*5,z:state.hero.z+Math.cos(a)*5,yaw:0,valid:false};$('creation-placement').hidden=false;$('placement-title').textContent=exact.name;updatePlacement();
}
function updatePlacement(){
 if(!placing)return;try{const def=R.Creation.placement(state,placing.blueprint,placing.x,placing.z,placing.yaw,R.creationContext());for(const k of R.MATERIALS)if(state.pack[k]<def.cost[k])throw Error('Gather or trade for the missing '+k+'.');placing.valid=true;$('placement-help').textContent='Click the ground or press E to place. R rotates. Esc cancels.';}catch(e){placing.valid=false;$('placement-help').textContent=e.message;}view.placement=placing;
}
function rotateCreation(){if(!placing)return;placing.yaw=placing.yaw>=180?-165:placing.yaw+15;updatePlacement();}
function cancelCreation(){placing=null;view.placement=null;$('creation-placement').hidden=true;clearInput();}
function commitCreation(){if(!placing)return;const p=placing;if(change(()=>R.create(state,p.blueprint,p.x,p.z,p.yaw),'Your creation now belongs to this world.')){cancelCreation();note(523,.5);note(784,.5,.03,.15);}}
function startRehearsal(b){
 const session=makeRehearsal(b);studio?.close();save();const original=state;rehearsal={original,session,blueprint:structuredClone(b)};state=session.world;placing=null;view.placement=null;view.atlas=false;view.yaw=0;view.pitch=.5;saveAt=0;lastHistory=state.revision;lastDiscovered=state.discoveries.length;lastResult=null;acc=0;clearInput();$('rehearsal-bar').hidden=false;hud();notice('Try the real behavior. T uses an attuned relic; E inspects a nearby creation.');
}
function returnRehearsal(){
 if(!rehearsal)return;const lab=rehearsal,r=rehearsalReport(lab.session);if(activity)leavePavilion();if(modal)closePanel();cancelCreation();state=lab.original;rehearsal=null;$('rehearsal-bar').hidden=true;saveAt=state.tick;lastHistory=state.revision;lastDiscovered=state.discoveries.length;lastResult=null;acc=0;clearInput();view.atlas=false;R.Creation.remember(state,`Living rehearsal · ${r.name}: ${r.damage} damage, ${r.healing} net healing, ${r.deliveries} deliveries. Your world materials stayed outside.`);save();if(studio){studio.results.push(r);if(studio.results.length>20)studio.results.shift();}openFoundry(lab.blueprint);
}
function creationDetails(id){
 const e=state.creation.instances.find(e=>e.id===id);if(!e)return;const b=e.blueprint,d=R.Creation.compile(b);
 openPanel(b.name,'YOUR AUTHORED '+b.kind.toUpperCase(),`<p>This instance keeps the exact form and behavior you accepted. Editing its recipe creates a different possibility.</p>${facts([['Blueprint revision',b.revision],['Kind',b.kind],['Invested materials',costs(Object.fromEntries(Object.entries(e.investment).filter(([,n])=>n)))],...(b.kind==='creature'?[['Current intention',esc(e.task)],['Energy',e.energy+' / 100'],['Cargo',e.cargo?esc(e.cargo.item):'None']]:[])])}<div class="creation-detail-grid">${b.kind==='creature'?'<button id="creation-feed" class="button primary">Feed · 1 food</button>':''}${b.kind==='relic'?'<button id="creation-equip" class="button primary">Attune · use with T</button>':''}${b.kind==='instrument'?'<button id="creation-perform" class="button primary">Play the score · 40 Breath</button>':''}${b.kind==='trial'?'<button id="creation-trial" class="button primary">Enter this authored trial</button>':''}<button id="creation-variation" class="button subtle">Create a variation</button><button id="creation-reclaim" class="button subtle">Reclaim materials</button></div><h3>What this design does</h3><p>${b.kind==='creature'?b.rules.map(r=>esc(r.when)+' → '+esc(r.do)).join('<br>'):b.kind==='instrument'?esc(b.voice)+' waves, '+b.score.join(' · '):b.kind==='relic'?esc(b.verb)+' · '+d.move.damage+' power · '+d.move.reach+' reach':b.kind==='trial'?b.course.length+' sigils · '+b.seconds+' seconds · '+b.order:'Walking decks support movement; solid parts block movement and projectiles.'}</p><p class="small">Reclamation returns this instance’s actual material investment. Food already consumed and its energy do not return.</p>`,'creation');
 bind('creation-feed',()=>{if(change(()=>R.Creation.feed(state,id)))creationDetails(id);});bind('creation-equip',()=>{if(change(()=>R.Creation.equip(state,id))){closePanel();notice('Attuned. Press T to use '+b.name+'.');}});bind('creation-perform',()=>{if(change(()=>R.Creation.perform(state,id))){if(!sound)toggleSound();closePanel();notice('The score moves through the world. Stand where its waves can reach you.');}});bind('creation-trial',()=>{if(change(()=>R.enterTrial(state,id))){closePanel();view.atlas=false;}});bind('creation-variation',()=>{closePanel();openFoundry(R.Creation.branch(b));});bind('creation-reclaim',()=>{if(change(()=>R.reclaimCreation(state,id),'The invested materials returned to your pack.'))closePanel();});
}
bind('open-creator',()=>openFoundry());bind('creation-power',()=>fire('creation'));bind('placement-commit',commitCreation);bind('placement-rotate',rotateCreation);bind('placement-cancel',cancelCreation);bind('rehearsal-return',returnRehearsal);
$('touch-run').onpointerdown=e=>{e.preventDefault();keys.touchRun=true;e.target.setPointerCapture(e.pointerId);};for(const type of ['pointerup','pointercancel','lostpointercapture'])$('touch-run').addEventListener(type,()=>delete keys.touchRun);
// Human-reviewed local agent proposals. No autonomous placement or authority claim.
globalThis.aweCreator=Object.freeze({
 schema:R.Creation.SCHEMA,
 example:kind=>R.Creation.seed(kind),
 inspect:()=>({profile:R.PROFILE,materials:{...(rehearsal?rehearsal.original:state).pack},creationKinds:[...R.Creation.KINDS],invited:state.creation.grants.agent,instances:state.creation.instances.map(e=>({id:e.id,name:e.blueprint.name,kind:e.blueprint.kind,revision:e.blueprint.revision}))}),
 preview:raw=>R.Creation.compile(raw),
 propose:raw=>{if(rehearsal||!state.creation.grants.agent)throw Error('The human has not invited local blueprint proposals.');if(state.creation.proposals.length>=4)throw Error('Four proposals are awaiting review.');const b=R.Creation.compile(raw).blueprint;state.creation.proposals.push(b);notice('A local agent blueprint is ready for review in the Foundry shelf.');return {acceptedForReview:true,name:b.name,instanceCreated:false,materialsSpent:false};}
});
